prices = {"mouse": 499, "keyboard": 1299, "monitor": 8999, "cable": 199, "webcam": 849}
with_gst = {item: round(price * 1.18, 2) for item, price in prices.items()}
premium = sorted([item for item, price in with_gst.items() if price > 1000])
print(with_gst)
print(premium)

slides.tests:
expected = {"mouse": 588.82, "keyboard": 1532.82, "monitor": 10618.82, "cable": 234.82, "webcam": 1001.82}
for item, value in expected.items():
    assert item in with_gst, f"with_gst is missing {item}. Build it from prices.items()."
    assert abs(with_gst[item] - value) < 0.01, f"{item} with 18% GST should be {value}, but with_gst has {with_gst[item]}. Multiply by 1.18 and round to 2 decimals."
assert premium == ["keyboard", "monitor", "webcam"], f"premium should be ['keyboard', 'monitor', 'webcam'], not {premium}. Look at the webcam: ₹849 becomes ₹1001.82 after GST."
assert any(isinstance(n, ast.DictComp) for n in ast.walk(__tree__)), "Build with_gst with a dict comprehension: {item: ... for item, price in prices.items()}."
